import { COVER_ANCHORED_VIDEO_THEME_BLUEPRINTS } from "./video-theme-cover-blueprints";

export const VIDEO_PROMPT_SECTION_LABELS = [
  "Subject / Character",
  "Action / Motion",
  "Scene / Environment",
  "Camera / Shot / Lens",
  "Lighting / Atmosphere",
  "Style / Mood / Palette",
  "Sound / Audio",
  "Duration / Aspect Ratio / Resolution",
  "Continuity",
  "Negative Constraints"
] as const;

export type VideoPromptSectionLabel = (typeof VIDEO_PROMPT_SECTION_LABELS)[number];

export type VideoPromptValidation = {
  valid: boolean;
  errors: string[];
  sections: Partial<Record<VideoPromptSectionLabel, string>>;
};

const sectionAliases: Record<VideoPromptSectionLabel, string[]> = {
  "Subject / Character": ["subject", "character"],
  "Action / Motion": ["action", "motion"],
  "Scene / Environment": ["scene", "environment"],
  "Camera / Shot / Lens": ["camera", "shot", "lens"],
  "Lighting / Atmosphere": ["lighting", "atmosphere"],
  "Style / Mood / Palette": ["style", "mood", "palette"],
  "Sound / Audio": ["sound", "audio"],
  "Duration / Aspect Ratio / Resolution": ["duration", "aspect ratio", "resolution"],
  Continuity: ["continuity"],
  "Negative Constraints": ["negative constraints", "negative"]
};

const cameraMotionPattern = /\b(push(?:[- ]?ins?)?|pull(?:[- ]?outs?)?|dolly|tracks?|tracking|moves?|slides?|gimbal|whip[- ]?pans?|pans?|tilts?|zooms?|orbits?|crane|handheld|static|locked[- ]?off|rack focus|arcs?|reveal)\b/i;
const lensPattern = /\b(?:\d{1,3}\s*mm|wide[- ]?angle|telephoto|macro|anamorphic|lens)\b/i;
const environmentPressurePattern = /\b(?:rain|wind|breeze|snow|steam|smoke|mist|heat|cold|warm|dust|crowd|crowded|traffic|water|sea|surf|air|room|studio|salon|café|restaurant|office|setting|movement|moving|fabric|surfaces?|reflections?|shadows?|weather|neon|flicker|sunlight|sunset|light|lamp|fog|humidity|pressure|daylight|glow|haze|workplace|window|garden|kitchen|table|floor|wall|shelf|plant|fireplace|sky|waterfront|pavement|outdoor|background|slide|diagram|beach|meadow|mountain)\b/i;
const microActionPattern = /\b(?:hand|hands|finger|fingers|breath|breathing|blink|eyes|gaze|jaw|lips|mouth|shoulder|shoulders|wrist|grip|swallow|posture|hair|fabric|paper|card|ring|tool|texture|steam|paw|paws|foot|feet|contact)\b/i;
const soundAnchorPattern = /\b(?:sounds?|audio|music|ambience|hum|buzz|ventilation|whisper|voice|footsteps?|click|rustle|silence|echo|motif|reflection|chime|splash|tone|narration|dialogue|applause|laughter|breath|pencil|paper|chair|scissors|espresso|ceramic|glass|clock|engine|relay|surf|waves?|cap|ring|bark|meow|purr|chirp|jingle|paws?|tool|machine|keyboard|envelope|instrument|bell|cloth|fabric|water|wind|sizzle|chop|scrape|pour|room tone)\b/i;
const finalFramePattern = /\b(?:final (?:frame|image|shot)|ending (?:frame|image|shot)|ends? on|finish(?:es)? on|last frame)\b/i;
const unsafePromptPattern = /\b(?:child porn|sexual(?:ized)? minor|underage (?:sex|nude|nudity)|explicit sexual content|graphic gore)\b/i;

function headingPattern(label: VideoPromptSectionLabel): RegExp {
  const aliases = sectionAliases[label].map((alias) => alias.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|");
  return new RegExp(`^\\s*(?:\\[?\\s*)?(?:${aliases})(?:\\s*[/|,&-]\\s*(?:${aliases}))*(?:\\s*\\])?\\s*:` , "im");
}

function sectionBody(prompt: string, label: VideoPromptSectionLabel): string {
  const heading = headingPattern(label);
  const match = heading.exec(prompt);
  if (!match || match.index === undefined) return "";
  const start = match.index + match[0].length;
  const rest = prompt.slice(start);
  const next = /^\s*(?:\[?\s*)?(?:subject(?:\s*[/|,&-]\s*character)?|action(?:\s*[/|,&-]\s*motion)?|scene(?:\s*[/|,&-]\s*environment)?|camera(?:\s*[/|,&-]\s*(?:shot|lens))+|lighting(?:\s*[/|,&-]\s*atmosphere)?|style(?:\s*[/|,&-]\s*(?:mood|palette))+|sound(?:\s*[/|,&-]\s*audio)?|duration(?:\s*[/|,&-]\s*(?:aspect ratio|resolution))+|continuity|negative(?:\s+constraints)?)(?:\s*\])?\s*:/im.exec(rest);
  return (next ? rest.slice(0, next.index) : rest).trim();
}

export function validateVideoPrompt(prompt: string): VideoPromptValidation {
  const value = prompt.trim();
  const errors: string[] = [];
  const sections: Partial<Record<VideoPromptSectionLabel, string>> = {};
  if (!value) return { valid: false, errors: ["Prompt is required."], sections };
  if (value.length > 6000) errors.push("Prompt must be 6000 characters or fewer.");
  if (unsafePromptPattern.test(value)) errors.push("Prompt contains disallowed sexual or graphic safety content.");

  for (const label of VIDEO_PROMPT_SECTION_LABELS) {
    const body = sectionBody(value, label);
    if (!body) errors.push(`Missing ${label} section.`);
    else sections[label] = body;
  }

  const camera = sections["Camera / Shot / Lens"] ?? "";
  const action = sections["Action / Motion"] ?? "";
  const environment = sections["Scene / Environment"] ?? "";
  const sound = sections["Sound / Audio"] ?? "";
  const continuity = sections.Continuity ?? "";
  if (action && !/\b(?:moves?|turns?|walks?|runs?|reaches?|looks?|shifts?|rises?|raises?|falls?|opens?|closes?|leans?|dances?|speaks?|breathes?|drifts?|pans?|tilts?|zooms?|tracks?|shows?|reveals?|performs?|delivers?|demonstrates?|gives?|leads?|works?|lifts?|pours?|cuts?|holds?|nods?|smiles?|asks?|builds?|creates?|adds?|animates?|introduces?|guides?|explains?|prepares?|assembles?|presses?|wraps?|decorates?|exchanges?|passes?|counts?|finishes?|starts?|preserves?|focuses?|makes?|aligns?|settles?|traces?|executes?|uses?|touches?|receives?|completes?|tries?|changes?|acts?|hits?|warms?)\b/i.test(action)) {
    errors.push("Action / Motion must describe a concrete first action.");
  }
  if (camera && (!cameraMotionPattern.test(camera) || !lensPattern.test(camera))) {
    errors.push("Camera / Shot / Lens must include explicit camera movement and lens or framing detail.");
  }
  if (environment && !environmentPressurePattern.test(environment)) errors.push("Scene / Environment must include a physical or environmental pressure/detail.");
  if (value && !microActionPattern.test(value)) errors.push("Prompt must include a body micro-action or tactile detail.");
  if (sound && !soundAnchorPattern.test(sound)) errors.push("Sound / Audio must include an audible or visual anchor.");
  if (value && !finalFramePattern.test(`${continuity} ${value}`)) errors.push("Continuity must describe the final frame or ending image.");
  return { valid: errors.length === 0, errors, sections };
}

export function formatVideoPromptSections(sections: Partial<Record<VideoPromptSectionLabel, string>>): string {
  return VIDEO_PROMPT_SECTION_LABELS
    .map((label) => `${label}: ${String(sections[label] ?? "").trim()}`)
    .join("\n\n");
}

export function normalizeVideoThemePromptOutputSettings(prompt: string): string {
  const validation = validateVideoPrompt(prompt);
  if (!validation.valid) return prompt.trim();
  return formatVideoPromptSections({
    ...validation.sections,
    "Duration / Aspect Ratio / Resolution": "Use the externally selected duration, aspect ratio, and resolution as the highest-priority output settings. When no external setting is provided, use 15 seconds, 16:9 aspect ratio, and 720p resolution."
  });
}

export function videoThemePromptForEditor(prompt: string): string {
  const value = prompt.trim();
  const validation = validateVideoPrompt(value);
  if (validation.valid) {
    const sections = validation.sections;
    const content = String(sections["Subject / Character"] ?? "").split(/(?<=\.)\s+/)[0];
    const ending = String(sections.Continuity ?? "").match(/Final frame:\s*(.+)$/i)?.[1] ?? sections.Continuity ?? "";
    return [
      `Content: ${content}`,
      `Action: ${sections["Action / Motion"] ?? ""}`,
      `Scene: ${sections["Scene / Environment"] ?? ""}`,
      `Camera & look: ${[sections["Camera / Shot / Lens"], sections["Lighting / Atmosphere"]].filter(Boolean).join(" · ")}`,
      `Sound / dialogue: ${sections["Sound / Audio"] ?? ""}`,
      `Ending: ${ending}`
    ].join("\n");
  }
  const durationHeading = headingPattern("Duration / Aspect Ratio / Resolution");
  const match = durationHeading.exec(value);
  if (!match || match.index === undefined) return value;
  const continuityHeading = headingPattern("Continuity");
  const trailing = value.slice(match.index + match[0].length);
  const next = continuityHeading.exec(trailing);
  const end = next && next.index !== undefined
    ? match.index + match[0].length + next.index
    : value.length;
  return `${value.slice(0, match.index)}${value.slice(end)}`.trim().replace(/\n{3,}/g, "\n\n");
}

type CompactVideoThemeBlueprint = {
  focus: string;
  action: string;
  scene: string;
  camera: string;
  lighting: string;
  style: string;
  sound: string;
  ending: string;
};

function compactBlueprint(value: string): CompactVideoThemeBlueprint {
  const parts = value.split("|");
  if (parts.length !== 7) throw new Error(`Video theme blueprint must contain exactly 7 fields; received ${parts.length}.`);
  const [focus, action, scene, camera, lighting, sound, ending] = parts;
  return {
    focus,
    action,
    scene,
    camera,
    lighting,
    style: "Keep the palette, material behavior, framing discipline, and emotional tone specific to this theme; grounded cinematic realism, never a generic montage.",
    sound,
    ending
  };
}

